def get(s, a):

global qv

if (s, a) not in qv:

return 0

return qv[(s, a)]

def update(s, a, s1, r):

global qv

nows = get(s, a)

m0 = get(s1, 0)

m1 = get(s1, 1)

if m0 < m1:

m0 = m1

qv[(s, a)] = nows + LEARNING\_RATE \* (r + DISCOUNT\_FACTOR \* m0 - nows)

